symbol=sys.argv[1];data=broker.BrokerData(search.ROOT/'.tmp/launch-research/exness-data',[f'2025-{m:02}' for m in range(1,9)],[symbol]);target=search.ROOT/f'.tmp/prop-speed/lowrr-{symbol}.so';subprocess.run(['g++','-O3','-std=c++17','-shared','-fPIC',str(search.ROOT/'scripts/research/launch/broker_account_screen.cpp'),'-o',str(target)],check=True);lib=ctypes.CDLL(str(target));run=lib.broker_screen;D=ctypes.POINTER(ctypes.c_double);I=ctypes.POINTER(ctypes.c_int);B=ctypes.POINTER(ctypes.c_byte);run.argtypes=[ctypes.c_int,ctypes.c_int]+[D]*9+[B]+[D]*3+[I,ctypes.c_int,ctypes.c_int]+[ctypes.c_double]*8+[D,D,ctypes.c_int];run.restype=ctypes.c_int;ptr=lambda x:x.ctypes.data_as(D)
def simulate(c,start,end):
 family,tf,n,stop,rr,hold=c;sig,atr=data.feature(family,tf,n);begin=int(np.searchsorted(data.t,search.stamp(start)));finish=int(np.searchsorted(data.t,search.stamp(end)));out=np.zeros(10);trades=np.zeros((4000,9));rc=run(len(data.t),1,*[ptr(x) for x in data.native],ptr(atr),sig.ctypes.data_as(B),ptr(data.t),ptr(data.contracts),ptr(data.ticks),data.inverse.ctypes.data_as(I),begin,finish,.5,10,stop,rr,hold*tf*60000,5.25,.75,25000,ptr(out),ptr(trades),len(trades));assert rc==0;count=int(out[4]);assert count<=len(trades);return dict(returnPct=(out[0]/25000-1)*100,drawdownPct=out[1],trades=count,winRatePct=(trades[:count,6]>0).mean()*100 if count else None,profitFactor=out[2]/out[3] if out[3] else None,failed=bool(out[7]))
