 periods=[simulate(c,'2025-01-20','2025-03-01'),simulate(c,'2025-03-01','2025-05-01')];rows.append(dict(configuration=dict(zip(['family','minutes','n','stop','rr','hold'],c)),periods=periods,minimumReturn=min(x['returnPct'] for x in periods),worstDD=max(x['drawdownPct'] for x in periods),minimumTrades=min(x['trades'] for x in periods)))
